def strip_comments_and_strings(text: str) -> str:
    res = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] == '"':
            # string literal
            i += 1
            while i < n and text[i] != '"':
                if text[i] == '\\' and i + 1 < n:
                    i += 2
